// Meter-to-cash worklists: queues, a paged case table and a case panel (VEE tests, read history, Activity Sequence
// trace, analyst actions). Everything shown comes from the engine views; this module only renders and sends actions.
import {escapeText as e} from './customer-view.js';
const QUEUE_ORDER=['VEE_REVIEW','ESTIMATION','SUPERVISOR','FIELD','BILLING'];
const ACTIONS={accept:'Accept as read',estimate:'Estimate',override:'Override value',field_order:'Field order',escalate:'Escalate'};
export const money=n=>Number.isFinite(n)?n.toLocaleString('en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:n>=1000?0:2}):'—';
const pct=n=>Number.isFinite(n)?Math.round(n*100)+'%':'—';
export const num=n=>Number.isFinite(n)?n.toLocaleString('en-CA'):'—';
const words=s=>String(s??'').replaceAll('_',' ');
export function parseRoute(hash){const m=String(hash||'').match(/^#\/worklists(?:\/([A-Z_]+))?(?:\/case\/([\w.:-]+))?$/);return m?{queue:m[1]&&m[1]!=='ALL'?m[1]:null,caseId:m[2]||null}:null;}
export function routeHash({queue=null,caseId=null}={}){return '#/worklists'+(queue||caseId?'/'+(queue||'ALL'):'')+(caseId?'/case/'+caseId:'');}
// Backlog sparkline over the days up to the view date (SVG path in a 100×24 box).
export function sparkPath(series,width=100,height=24){const s=(series||[]).slice(-120);if(s.length<2)return '';const max=Math.max(1,...s);return s.map((v,i)=>`${i?'L':'M'}${(i/(s.length-1)*width).toFixed(1)} ${(height-v/max*height).toFixed(1)}`).join(' ');}
function historyChart(h){const rows=h.filter(x=>x.month>0);if(!rows.length)return '';const vals=rows.flatMap(x=>[x.consumption,x.expected]).filter(Number.isFinite),max=Math.max(1,...vals.map(Math.abs)),w=100/rows.length;
 return `<svg class="wl-chart" viewBox="0 0 100 44" preserveAspectRatio="none" role="img" aria-label="Consumption by month against expected">${rows.map((x,i)=>{const c=x.consumption,ex=x.expected,hgt=Number.isFinite(c)?Math.min(40,Math.abs(c)/max*40):0,cls=x.status==='estimated'?'est':x.status==='adjusted'?'adj':x.caseId?'flag':'ok';
  return `<rect class="${cls}" x="${(i*w+w*.18).toFixed(2)}" y="${(42-hgt).toFixed(2)}" width="${(w*.64).toFixed(2)}" height="${hgt.toFixed(2)}"><title>${e(x.readAt?.slice(0,10))}: ${num(c)} (expected ${num(ex)})</title></rect>${Number.isFinite(ex)?`<line x1="${(i*w+w*.1).toFixed(2)}" x2="${(i*w+w*.9).toFixed(2)}" y1="${(42-Math.min(40,ex/max*40)).toFixed(2)}" y2="${(42-Math.min(40,ex/max*40)).toFixed(2)}"/>`:''}`;}).join('')}</svg>`;}
function billMarkup(d){return `<section class="detail-section"><h3>Billing document · ${e(words(d.billStatus))}</h3><div class="detail-line"><span>Document</span><strong class="mono">${e(d.id)}</strong></div><div class="detail-line"><span>Rate · period</span><strong>${e(d.rateCategory)} · ${e(d.periodStart.slice(0,10))} to ${e(d.periodEnd.slice(0,10))}</strong></div><table class="wl-bill"><tbody>${d.lines.map(l=>`<tr><td>${e(l.description)}<small>${l.quantity!=null?num(l.quantity)+' '+e(l.unit||'')+' × '+l.rate:''}</small></td><td>${money(l.amount)}</td></tr>`).join('')}<tr><td>Tax</td><td>${money(d.tax)}</td></tr><tr class="total"><td>Total</td><td>${money(d.totalAmount)}</td></tr></tbody></table>${d.truth?`<p class="small-note">Truth: ${money(d.truth.totalAmount)} · expected ${money(d.truth.expectedTotal)}.</p>`:''}</section>`;}
export function installWorklists({getClient,onShowPremise=()=>{},onSettings=()=>{},onMarkers=()=>{},onDate=()=>{},onWatch=()=>{},toast=()=>{}}){
 const $=id=>document.getElementById(id);let route={queue:null,caseId:null},sort='age',status='open',search='',page=1,truth=false,summary=null,busy=0;
 const client=()=>getClient();
 function setStatus(text){$('wl-status').textContent=text||'';}
 async function load(){const m2c=client();
  if(!m2c){$('wl-kpis').innerHTML='';$('wl-queues').innerHTML='';$('wl-table').innerHTML=`<div class="wl-empty"><h2>Worklists need the engine</h2><p>Open an engine town (for example <code>?town=ayr</code> on the hosted site), or run <code>uv run utilsim serve</code> locally and add <code>?engine=http://127.0.0.1:8010</code>. The engine replays a year of reads, VEE and work queues for the town.</p></div>`;$('wl-case').innerHTML='';$('wl-pager').innerHTML='';setStatus('');return;}
  const ticket=++busy;setStatus('Running the engine…');
  try{summary=await m2c.summary();}catch(err){quiet(err);return;}if(ticket!==busy)return;if(!m2c.asOf)m2c.setAsOf(summary.asOf);$('wl-asof').value=m2c.asOf;renderSummary();
  // The table and the case load independently: a superseded table request never blocks the case panel.
  await Promise.all([loadTable(ticket).catch(quiet),route.caseId?loadCase(route.caseId,ticket):renderEmptyCase()]);
  if(ticket!==busy)return;setStatus((summary.warnings||[]).join(' ')+(m2c.actions.length?` ${m2c.actions.length} action${m2c.actions.length>1?'s':''} of yours replayed.`:''));onMarkers(summary);}
 function quiet(err){if(!err.superseded){setStatus(err.message);toast(err.message);}}
 const table=()=>loadTable().catch(quiet);
 function renderSummary(){const k=summary.kpis,rel=Object.values(summary.reliability||{}),queues=QUEUE_ORDER.map(id=>summary.queues.find(q=>q.id===id)).filter(Boolean),allOpen=queues.reduce((a,q)=>a+q.open,0);
  $('wl-kpis').innerHTML=[['Reads to date',num(k.reads),`${(k.autoAccepted/Math.max(1,k.actual)*100).toFixed(1)}% auto-accepted`],['Flagged by VEE',num(k.flagged),`${num(k.missing)} missing reads`],['Open cases',num(k.casesOpen),`${num(k.casesResolved)} resolved`],['Days to release',k.avgDaysToRelease==null?'—':k.avgDaysToRelease.toFixed(1),'average per case'],['Cost to date',money(k.costs.total),`${money(k.costs.labor)} labour · ${money(k.costs.reads)} reads`],['Carrying cost',money(k.carry),'bills held by exceptions'],['VEE vs truth',k.vee.precision==null?'—':`${pct(k.vee.precision)} / ${pct(k.vee.recall)}`,'precision / recall'],...(rel.length?[['Outages from the map',`${num(rel.reduce((a,r)=>a+r.customerMinutes,0))} cust-min`,`${num(rel.reduce((a,r)=>a+r.customersInterrupted,0))} customers${summary.reliability.electric?` · SAIDI ${summary.reliability.electric.saidiMinutes} min · ${num(summary.reliability.electric.lastGasps)} last gasps`:''}`]]:[]),...(summary.weather?[['Weather',`${Math.round(summary.weather.tempC)}°C`,`${summary.weather.coldDays} days at −15°C or colder`,summary.weather.series]]:[]),...(summary.billing?[['Billed to date',money(summary.billing.billed),`${num(summary.billing.invoices)} invoices · ${num(summary.billing.blocked)} blocked`],['Collected',money(summary.billing.collected),`${money(summary.billing.overdue)} overdue`],['Days to invoice',summary.billing.avgDaysToInvoice==null?'—':summary.billing.avgDaysToInvoice.toFixed(1),`${summary.billing.avgDaysToPay==null?'—':summary.billing.avgDaysToPay.toFixed(0)} days to pay`],['Billing error',money(summary.billing.billingError),'billed vs simulation truth'],['Receivable carry',money(summary.billing.receivableCarry),`${money(summary.billing.billingCarry)} billing carry`]]:[])]
   .map(([t,v,s,series])=>`<div class="wl-kpi"><span>${e(t)}</span><strong>${e(v)}</strong><small>${e(s)}</small>${series?`<svg class="wl-temp" viewBox="0 0 100 24" preserveAspectRatio="none" aria-hidden="true"><path d="${sparkPath(series.map(x=>x+30))}"/></svg>`:''}</div>`).join('');
  $('wl-queues').innerHTML=`<button data-wl-queue="" aria-current="${route.queue?'false':'page'}"><span class="wl-q-name">All queues</span><strong>${num(allOpen)}</strong></button>`+queues.map(q=>`<button data-wl-queue="${q.id}" aria-current="${route.queue===q.id?'page':'false'}"><span class="wl-q-name">${e(q.label)}</span><strong>${num(q.open)}</strong><span class="wl-aging">${Object.entries(q.aging).map(([b,n])=>`<i title="${n} open ${b} business days">${n}</i>`).join('')}</span><svg viewBox="0 0 100 24" preserveAspectRatio="none" aria-hidden="true"><path d="${sparkPath(q.series.backlog)}"/></svg></button>`).join('')
   +`<p class="small-note wl-rpa">RPA rules: ${summary.rpaTypes.length?summary.rpaTypes.map(t=>e(words(t).toLowerCase())).join(', '):'none'}.</p>`;
  document.querySelectorAll('[data-wl-queue]').forEach(b=>b.onclick=()=>{page=1;go({queue:b.dataset.wlQueue||null,caseId:null});});}
 async function loadTable(ticket=busy){const m2c=client();const data=await m2c.queue({queue:route.queue,status,sort,page,pageSize:25,search:search||undefined});if(ticket!==busy)return;
  $('wl-table').innerHTML=data.rows.length?`<table><thead><tr><th>Case</th><th>Premise</th><th>Utility</th><th>Read</th><th>Age</th><th>Confidence</th><th>Disposition</th><th>Impact</th><th>Status</th></tr></thead><tbody>${data.rows.map(r=>`<tr data-wl-case="${e(r.caseId)}" tabindex="0" aria-selected="${r.caseId===route.caseId}"><td><span class="wl-type">${e(r.icon)} ${e(r.label)}</span><small class="mono">${e(r.caseId)}</small></td><td>${e(r.address)}<small class="mono">${e(r.accountId)}</small></td><td>${e(r.commodity)}<small>${e(r.technology)}</small></td><td>${e(r.readDate)}</td><td>${r.ageDays} d</td><td>${r.confidence==null?'<span class="wl-na">n/a</span>':`<span class="wl-gauge" style="--v:${Math.round(r.confidence*100)}%"></span>${pct(r.confidence)}`}</td><td>${e(r.disposition)}</td><td>${money(r.impact)}</td><td>${e(words(r.status))}<small>${e(r.assignee||'unassigned')}</small></td></tr>`).join('')}</tbody></table>`
   :`<div class="wl-empty"><p>No ${status==='open'?'open ':''}cases ${route.queue?'in this queue ':''}on ${e(client().asOf)}.</p></div>`;
  const pages=Math.max(1,Math.ceil(data.total/data.pageSize));
  $('wl-pager').innerHTML=`<span>${num(data.total)} case${data.total===1?'':'s'}</span><button class="small-link" data-wl-page="-1" ${page<=1?'disabled':''}>Previous</button><span>Page ${page} of ${pages}</span><button class="small-link" data-wl-page="1" ${page>=pages?'disabled':''}>Next</button>`;
  document.querySelectorAll('[data-wl-page]').forEach(b=>b.onclick=()=>{page=Math.max(1,page+Number(b.dataset.wlPage));table();});
  document.querySelectorAll('[data-wl-case]').forEach(row=>{const open=()=>go({queue:route.queue,caseId:row.dataset.wlCase});row.onclick=open;row.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();open();}};});}
 function renderEmptyCase(){$('wl-case').innerHTML='<div class="wl-empty"><p>Select a case to see the VEE decision, the read history and what happened.</p></div>';}
 async function loadCase(id,ticket=busy){const m2c=client();let c;try{c=await m2c.caseView(id,truth);}catch(err){if(!err.superseded)$('wl-case').innerHTML=`<div class="wl-empty"><p>${e(err.message)}</p></div>`;return;}if(ticket!==busy)return;
  const d=c.decision,canAct=m2c.canAct(),tests=d.tests.map(t=>`<li class="wl-test ${t.outcome}"><div><strong>${e(t.test)}</strong><span>${e(words(t.outcome))}${t.contribution?` · ${t.contribution.toFixed(2)}`:''}</span></div><span class="wl-bar" style="--v:${Math.round(t.contribution/0.25*100)}%"></span><p>${e(t.rationale)}</p></li>`).join('');
  const events=c.events.map(ev=>{const cost=ev.payload.cost,total=cost.labor+cost.system+cost.cx;return `<li><span class="wl-ev-icon">${e(ev.payload.icon)}</span><div><strong>${e(ev.payload.label)}</strong><small>${e(ev.occurredAt.replace('T',' ').slice(0,16))} UTC${total?` · ${money(total)}`:''}${ev.payload.analyst||ev.payload.supervisor?` · ${e(ev.payload.analyst||ev.payload.supervisor)}`:''}${ev.payload.action?` · ${e(words(ev.payload.action))}`:''}</small></div></li>`;}).join('');
  const actions=c.actions.length?`<div class="wl-actions">${c.actions.map(a=>a==='override'?`<span class="wl-override"><input id="wl-override-value" type="number" min="0" step="any" placeholder="Register value" aria-label="Override register value"><button data-wl-act="override" ${canAct?'':'disabled'}>${ACTIONS[a]}</button></span>`:`<button data-wl-act="${a}" ${canAct?'':'disabled'}>${ACTIONS[a]}</button>`).join('')}</div>${canAct?'':`<p class="small-note">Actions are append-only: move the date to ${e(m2c.lastActionDay())} or later to act.</p>`}<p class="small-note">Your action is dated ${e(m2c.asOf)} and the engine replays the year with it.</p>`:'<p class="small-note">This case is closed on this date.</p>';
  $('wl-case').innerHTML=`<div class="eyebrow">CASE · ${e(c.caseId)}</div><h2>${e(c.icon)} ${e(c.label)}</h2><div class="wl-case-sub">${e(c.address)} · ${e(c.commodity)} ${e(c.read.direction)} · ${e(c.technology)}</div>
   <div class="home-tags"><span>${e(words(c.status))}</span><span>${e(c.queue?words(c.queue).toLowerCase():'')}</span>${c.outcome?`<span>${e(words(c.outcome))}</span>`:''}</div>
   <button class="outline-btn wl-show" id="wl-show-premise">Show on the map</button>${(c.fieldVisits||[]).map((v,k)=>`<button class="outline-btn wl-show" data-wl-watch="${k}">Watch the truck roll · ${e(v.day)} ${String(Math.floor(v.seconds/3600)).padStart(2,'0')}:${String(Math.floor(v.seconds%3600/60)).padStart(2,'0')}</button>`).join('')}
   <section class="detail-section"><h3>Read</h3>${[['Read date',c.readDate],['Register',`${num(c.read.registerValue)} ${c.read.unit}`],['Previous',`${num(c.read.previousRegisterValue)} ${c.read.unit}`],['Consumption',c.read.registerRegression?'Register went backwards':`${num(c.read.consumption)} ${c.read.unit}`],['Expected',`${num(d.expectedConsumption)} ${c.read.unit}`],['VEE status',words(c.read.veeStatus)],['Bill status',words(c.read.billStatus)],['SAP code',d.sapValidationCode?`${d.sapValidationCode} · ${d.sapCategory}`:'none'],['Bill impact',money(c.impact)]].map(([k,v])=>`<div class="detail-line"><span>${e(k)}</span><strong>${e(v)}</strong></div>`).join('')}${c.heldReadIds.length?`<p class="small-note">${c.heldReadIds.length} later read${c.heldReadIds.length>1?'s are':' is'} held by this case.</p>`:''}</section>
   ${c.billingDocument?billMarkup(c.billingDocument):''}
   <section class="detail-section"><h3>VEE decision · ${d.confidence==null?'no read':pct(d.confidence)+' confidence'} · ${e(d.disposition)}</h3><ol class="wl-tests">${tests}</ol></section>
   <section class="detail-section"><h3>Read history</h3>${historyChart(c.history)}<p class="small-note">Bars: consumption per period (estimated, adjusted and flagged marked); lines: expected.</p><label class="wl-truth"><input type="checkbox" id="wl-truth" ${truth?'checked':''}> Show simulation truth</label>${truth&&c.truth?`<p class="small-note">Truth: ${e(words(c.truth.class))}${c.read.truth?` · true register ${num(c.read.truth.registerValue)}`:''}.</p>`:''}</section>
   <section class="detail-section"><h3>Actions</h3>${actions}</section>
   <section class="detail-section"><h3>Activity sequence</h3><ol class="wl-events">${events}</ol><a class="small-link wl-trace" href="#/process/${Number((c.readDate||c.createdAt).slice(5,7))}/${e(c.events[0]?.eventId||c.caseId+':0')}">Trace this Activity Sequence</a></section>`;
  $('wl-show-premise').onclick=()=>onShowPremise(c.premiseId);document.querySelectorAll('[data-wl-watch]').forEach(b=>b.onclick=()=>{const v=c.fieldVisits[Number(b.dataset.wlWatch)];onWatch({premiseId:c.premiseId,day:v.day,seconds:v.seconds});});$('wl-truth').onchange=ev=>{truth=ev.target.checked;loadCase(id);};
  document.querySelectorAll('[data-wl-act]').forEach(b=>b.onclick=async()=>{const type=b.dataset.wlAct,value=type==='override'?$('wl-override-value').value:null;if(type==='override'&&(value===''||Number(value)<0)){toast('Enter the register value to bill.');return;}
   b.disabled=true;try{await m2c.act(type,c.caseId,value);toast(`${ACTIONS[type]} recorded for ${m2c.asOf}.`);await load();}catch(err){if(!err.superseded)toast(err.message);b.disabled=false;}});}
 function go(next){route={...route,...next};const h=routeHash(route);if(location.hash!==h)location.hash=h;else open(route);}
 function open(r){const changedQueue=r.queue!==route.queue;route=r;if(changedQueue)page=1;load();}
 $('wl-asof').onchange=ev=>{const m2c=client();if(!m2c)return;m2c.setAsOf(ev.target.value);onDate(ev.target.value);page=1;load();};
 $('wl-sort').onchange=ev=>{sort=ev.target.value;page=1;table();};$('wl-filter-status').onchange=ev=>{status=ev.target.value;page=1;table();};
 let timer=0;$('wl-search').oninput=ev=>{clearTimeout(timer);timer=setTimeout(()=>{search=ev.target.value.trim();page=1;table();},250);};
 $('wl-settings').onclick=onSettings;
 $('wl-reset').onclick=()=>{const m2c=client();if(!m2c||!m2c.actions.length)return;m2c.reset();toast('Your actions were cleared; the engine replays the year without them.');load();};
 $('wl-export').onclick=()=>{const m2c=client();if(!m2c)return;const blob=new Blob([JSON.stringify(m2c.export(),null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=(m2c.townId||'town')+'-m2c-run.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
 return {open,refresh:load,get summary(){return summary;}};
}
